      renwu = "npc",
      role1 = 1113000,
      role2 = 101103,
      role3 = 101201,
      role6 = 11135003,
      roleanim = 1.1,
      sentence = "As I gripped the tiger tally and looked out upon the hall, I felt like I could see beyond the hall door and all the myriad palace chambers, out onto the sweeping landscape of Luminor as the stars turned overhead.",
      next = {49}
    },
    [49] = {
      beijing = 4490,
