      role1 = 1113000,
      role2 = 101103,
      role3 = 101201,
      role6 = 11135003,
      roleanim = 1.1,
      sentence = "My father said that although you risked your life on the battlefield, at least you knew what you were up against: real swords and real spears.",
      next = {50}
    },
    [50] = {
      beijing = 4490,
      dhead = 1206,
