      role1 = 1113000,
      role2 = 101103,
      role3 = 101201,
      role6 = 11135003,
      roleanim = 1.1,
      sentence = "But sitting atop the throne in the imperial court, there are enemies coming from all directions. You let your guard down just a little, and you could lose everything.",
      next = {51}
    },
    [51] = {
      beijing = 4490,
      dhead = 1206,
      dialog = 1,
