      renwu = "npc",
      role1 = 1113000,
      role2 = 101103,
      role3 = 101201,
      role6 = 11135003,
      roleanim = 1.1,
      sentence = "Victor, I don't like fighting these covert battles, but I loathe to lose you more.",
      next = {52}
    },
    [52] = {
      beijing = 4490,
      dhead = 1201,
      dialog = 1,
