      renwu = "npc",
      role1 = 1113000,
      role2 = 101103,
      role3 = 101202,
      role6 = 11135003,
      roleanim = 1.1,
      sentence = "His lips fell upon the nape of my neck, along with a slight nip from his teeth and a tightening of his embrace.",
